import requests
terms=['"myotendinous-like" cardiac valve','fibromodulin lumican cardiac valve junction','Fmod Lum valve attachment heart']
for term in terms:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
 r=requests.get(u,params={'db':'pubmed','term':term,'retmax':10,'retmode':'json'},timeout=20)
 print('\nQUERY',term,'STATUS',r.status_code)
 ids=r.json().get('esearchresult',{}).get('idlist',[])
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()
  for i in ids:
   a=x['result'][i]; print(i,a.get('title',''),a.get('pubdate',''))
 else: print('No PubMed IDs')
